import{_ as i,o as a,c as t,an as o}from"./chunks/framework.D1f4kYqw.js";const u=JSON.parse('{"title":"Release notes","description":"","frontmatter":{},"headers":[],"relativePath":"release-notes.md","filePath":"release-notes.md","lastUpdated":null}'),r={name:"release-notes.md"};function s(l,e,n,p,d,c){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="Release-notes" tabindex="-1">Release notes <a class="header-anchor" href="#Release-notes" aria-label="Permalink to &quot;Release notes {#Release-notes}&quot;">​</a></h1><p>Every release of this package is published as a GitHub release. The most recent are reproduced below, as they were written there.</p><h2 id="v0.2.0" tabindex="-1">v0.2.0 <a class="header-anchor" href="#v0.2.0" aria-label="Permalink to &quot;v0.2.0 {#v0.2.0}&quot;">​</a></h2><p>Released 2026-08-06. <a href="https://github.com/EpiAware/ReparameterisedDistributions.jl/releases/tag/v0.2.0" target="_blank" rel="noreferrer">Read it on GitHub</a>.</p><p><a href="https://github.com/EpiAware/ReparameterisedDistributions.jl/compare/v0.1.0...v0.2.0" target="_blank" rel="noreferrer">Diff since v0.1.0</a></p><h5 id="Breaking-changes" tabindex="-1">Breaking changes <a class="header-anchor" href="#Breaking-changes" aria-label="Permalink to &quot;Breaking changes {#Breaking-changes}&quot;">​</a></h5><ul><li><p><strong>One hook per family</strong> — <code>_check_moments</code> is now folded into <code>to_native</code>. Families override a single hook instead of two. Update any custom families accordingly. (#84)</p></li><li><p><strong>Exported API rename</strong> — <code>_to_native</code> → <code>to_native</code>, <code>_native</code> → <code>native</code>. The underscore prefix is dropped. (#47)</p></li><li><p><strong>Registration surface cut from seven hooks to three</strong> — most families now need only <code>_to_native</code>, <code>_native</code>, and <code>_check_validity</code>. (#82)</p></li><li><p><strong>Infrastructure modernised</strong> onto EpiAwarePackageTools managed kit. (#23)</p></li></ul><h5 id="New-features" tabindex="-1">New features <a class="header-anchor" href="#New-features" aria-label="Permalink to &quot;New features {#New-features}&quot;">​</a></h5><ul><li><p><strong><code>reparameterise()</code></strong> — wrap any distribution so its parameters are its moments (#19). The core verb. (#26)</p></li><li><p><strong>Closed-form moment conversions</strong> for several families:</p><ul><li><p><code>Gamma(mean, sd)</code>, <code>Gamma(mean, var)</code>, <code>Gamma(mean, shape)</code> — exact algebra, no solve. (#27)</p></li><li><p><code>NegativeBinomial(mean, overdispersion)</code> — overdispersion as excess variance relative to Poisson. (#27)</p></li><li><p><code>Beta(mean, sd)</code> and <code>InverseGaussian(mean, sd)</code>. (#75)</p></li><li><p><code>SkewNormal(location, scale, tail_prob)</code> — parameterised by a tail probability rather than skew. (#62)</p></li><li><p><code>Exponential(rate)</code> and <code>Gamma(shape, rate)</code> — rate parameterisations. (#61)</p></li><li><p><code>NegativeBinomial(mean, reciprocal_dispersion)</code> — reciprocal dispersion alternative. (#60)</p></li></ul></li><li><p><strong>Numeric moment matching</strong> via a solver extension using <code>Roots.jl</code>, with <code>Weibull</code> as its first user. Compatible with every major AD backend. (#78, #85)</p></li><li><p><strong>Family-agnostic <code>rescale</code> verb</strong> — shift a distribution&#39;s moments without knowing its parameterisation. (#59)</p></li><li><p><strong>Fully inferred construction</strong> — family names threaded as <code>Val</code> so type inference works through construction. (#49)</p></li></ul><h5 id="Fixes" tabindex="-1">Fixes <a class="header-anchor" href="#Fixes" aria-label="Permalink to &quot;Fixes {#Fixes}&quot;">​</a></h5><ul><li><p>Author credits aligned per community ruling (#48). (#64)</p></li><li><p>Replaced broken ConvolvedDistributions link with correct <code>/dev/</code> docs URL. (#63)</p></li><li><p>Docs deploy URL now uses <code>https://</code> so CSS resolves on the deployed site. (#33, #34)</p></li></ul><h5 id="Documentation" tabindex="-1">Documentation <a class="header-anchor" href="#Documentation" aria-label="Permalink to &quot;Documentation {#Documentation}&quot;">​</a></h5><ul><li><p>Full README and getting-started overview refresh to org standards. (#79)</p></li><li><p>Release notes page now points at GitHub Releases. (#76)</p></li><li><p>Added a Related packages section to the README. (#50)</p></li><li><p>Logo, richer REPL show, and scaffold text improvements. (#46)</p></li></ul><h5 id="Infrastructure" tabindex="-1">Infrastructure <a class="header-anchor" href="#Infrastructure" aria-label="Permalink to &quot;Infrastructure {#Infrastructure}&quot;">​</a></h5><ul><li><p>CI dependencies bumped: <code>actions/checkout</code> to v7, <code>actions/github-script</code> to v9, <code>julia-actions/setup-julia</code> to v3, <code>julia-actions/cache</code> to v3. (#28, #29, #30, #31)</p></li><li><p>Dependabot updates grouped and template sync repaired (#67, #66).</p></li><li><p>Julia dependency bumps (<code>JET</code>, compat updates). (#70, #74)</p></li><li><p>Other GitHub Actions group bumps. (#69, #73)</p></li></ul><p><strong>Merged pull requests:</strong></p><ul><li><p>ci(deps): Bump the github-actions group with 8 updates (#73) (@dependabot[bot])</p></li><li><p>chore(deps): Update JET requirement from 0.9, 0.10, 0.11 to 0.9, 0.10, 0.11, 0.12 in the julia group (#74) (@dependabot[bot])</p></li><li><p>feat: register Beta and InverseGaussian analytical moment conversions (#39) (#75) (@seabbs-bot)</p></li><li><p>docs: point the release-notes page at GitHub Releases (#72) (#76) (@seabbs-bot)</p></li><li><p>feat: numeric moment matching via a solver extension, with Weibull as its first user (#41) (#78) (@seabbs-bot)</p></li><li><p>docs: bring the README and getting-started overview back to org standards (#79) (@seabbs-bot)</p></li><li><p>refactor: cut the registration surface from seven hooks to three (#80) (#82) (@seabbs-bot)</p></li><li><p>refactor!: one hook per family — fold the validity guard into to_native (#84) (@seabbs-bot)</p></li></ul><p><strong>Closed issues:</strong></p><ul><li><p>Add support for an increased range of dists with analytical moment conversions (#39)</p></li><li><p>Numeric moment matching (#41)</p></li><li><p>Release (#65)</p></li><li><p>Point the release-notes docs page at GitHub Releases (#72)</p></li><li><p>Family registration is documented as a public extension path but half of it is private (_valid_moments, plus five more from #41) (#80)</p></li></ul><h2 id="v0.1.0" tabindex="-1">v0.1.0 <a class="header-anchor" href="#v0.1.0" aria-label="Permalink to &quot;v0.1.0 {#v0.1.0}&quot;">​</a></h2><p>Released 2026-07-31. <a href="https://github.com/EpiAware/ReparameterisedDistributions.jl/releases/tag/v0.1.0" target="_blank" rel="noreferrer">Read it on GitHub</a>.</p><p>First release. Adds core functionality as well as package infrastructure.</p><p><strong>Closed issues:</strong></p><ul><li><p>Add package infrastructure (#1)</p></li><li><p>Update to hosting at EpiAware (#3)</p></li><li><p>Update to use EpiAware skeleton (#4)</p></li><li><p>Add mean and sd parameterisation for common univariate distributions (#5)</p></li><li><p>Gamma: mean and sd (#6)</p></li><li><p>Lognormal: mean and sd (#7)</p></li><li><p>Negative binomial parameterisations (#8)</p></li><li><p>Neg bin: mean and dispersion (#9)</p></li><li><p>Neg bin: mean and clustering factor (#10)</p></li><li><p>Neg bin: Log input (#11)</p></li><li><p>Neg bin: GLM optimised likelihood (#12)</p></li><li><p>Poisson (#13)</p></li><li><p>Poisson: Log input (#14)</p></li><li><p>Poisson: GLM optimised (#15)</p></li><li><p>Package rename (#16)</p></li><li><p>Explore DistributionFactories to see what the overlap is (#17)</p></li><li><p>Modernise onto current EpiAwarePackageTools infra (ad=true) + KIT AD harness (#18)</p></li><li><p>Core: AbstractReparameterisedDistribution + reparameterise() constructor (moment-param wrapper) (#19)</p></li><li><p>Closed-form mean+sd reparameterisations: LogNormal + Gamma (priority) + NegBinomial mean+overdispersion (#20)</p></li><li><p>Port the moment-parameterisation wrapper from CensoredDistributions (CD#725) (#21)</p></li><li><p>Triage the legacy #7–#17 per-family backlog against the generic wrapper (#22)</p></li><li><p>Manual setup for ReparameterisedDistributions (Codecov, Pages, branch protection, registration) (#24)</p></li><li><p>Scaffold text left in docs. (#36)</p></li><li><p>Remove refs to other packages/epi people won&#39;t know (#37)</p></li><li><p>Add a approach to get the original params of the distribution i.e the internal params (#38)</p></li><li><p>Review AD support and make sure all working (#40)</p></li><li><p>Package logo missing (#42)</p></li><li><p>_to_native (#43)</p></li><li><p>Custom show method (#44)</p></li><li><p>Type stability of reparameterised named tuple (#45)</p></li><li><p>Align author credits across Project.toml, CITATION.cff and docs (needs @seabbs ruling) (#48)</p></li><li><p>Family-agnostic mean rescaling verb (#52)</p></li><li><p>Register the reciprocal dispersion parameterisation for the negative binomial (#53)</p></li><li><p>Rate parameterisations for the exponential and gamma families (#54)</p></li><li><p>Register a skew-normal parameterisation keyed on a tail probability (#55)</p></li></ul><p>Every release, including any older than those above, is listed on the <a href="https://github.com/EpiAware/ReparameterisedDistributions.jl/releases" target="_blank" rel="noreferrer">releases page</a>.</p>',25)])])}const h=i(r,[["render",s]]);export{u as __pageData,h as default};
